// Adapted from tracer-net src/Tracer.Api/RateLimiting/WriteRateLimiter.cs @ 2c0f21f: lines 54-58 replaced by the
// fix the senior review proposes (docs/architecture.md:241, partition on the authenticated user, IP for failed auth),
// assuming app.UseRateLimiter() is moved after app.UseAuthentication() (src/Tracer.Api/Program.cs:86-91).
using System.Security.Claims;
using System.Threading.RateLimiting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.RateLimiting;
using Tracer.Api.Auth;

namespace Tracer.Api.RateLimiting;

/// <summary>
/// A global rate limiter aimed at the endpoints that change state.
///
/// <para>
/// <b>Only writes are limited.</b> A read is cheap and idempotent; a burst of
/// <c>GET</c>s is a client that is merely eager. A burst of <c>POST</c>/<c>PUT</c>/
/// <c>DELETE</c>s is the shape of a runaway script or a retry storm, and each one
/// costs a transaction, an audit entry, and — through the activity spine — webhook
/// deliveries and notifications fanned out to everyone watching. So reads pass
/// through unmetered and only mutating methods draw from the bucket.
/// </para>
/// <para>
/// <b>The bucket is per credential, not per process.</b> Partitioning by API key
/// means one team's misbehaving integration cannot spend everyone else's budget;
/// an unauthenticated caller (which can only reach <c>/api/health</c>) is bucketed
/// by remote address instead. The limit is a fixed window read from configuration
/// so an operator can tighten or loosen it without a redeploy.
/// </para>
/// </summary>
public static class WriteRateLimiter
{
    public const string PolicyName = "writes";

    public static IServiceCollection AddWriteRateLimiter(this IServiceCollection services)
    {
        services.AddRateLimiter(options =>
        {
            options.RejectionStatusCode = StatusCodes.Status429TooManyRequests;

            options.GlobalLimiter = PartitionedRateLimiter.Create<HttpContext, string>(context =>
            {
                if (!IsWrite(context.Request.Method))
                {
                    // Reads are never throttled: a NoLimiter partition draws from
                    // nothing and rejects nothing.
                    return RateLimitPartition.GetNoLimiter("read");
                }

                // Read lazily from the request's configuration rather than captured
                // at registration, so the value reflects the final merged config —
                // which is what lets a host (or a test) set the limit without this
                // code caring where it came from.
                var configuration = context.RequestServices.GetRequiredService<IConfiguration>();
                var permitLimit = configuration.GetValue<int?>("RateLimiting:PermitLimit") ?? 120;
                var windowSeconds = configuration.GetValue<int?>("RateLimiting:WindowSeconds") ?? 60;

                // Partition on the AUTHENTICATED caller (UseRateLimiter runs after
                // UseAuthentication in this adaptation), never on a header the caller
                // controls: a request whose key failed to authenticate is bucketed by
                // remote address, so guessing keys cannot mint fresh windows.
                var userId = context.User.FindFirstValue(ClaimTypes.NameIdentifier);
                var partitionKey = userId is not null
                    ? $"user:{userId}"
                    : $"ip:{context.Connection.RemoteIpAddress?.ToString() ?? "anonymous"}";

                return RateLimitPartition.GetFixedWindowLimiter(
                    partitionKey,
                    _ => new FixedWindowRateLimiterOptions
                    {
                        PermitLimit = permitLimit,
                        Window = TimeSpan.FromSeconds(windowSeconds),
                        QueueLimit = 0,
                    });
            });

            // A rejection is an error like any other, so it comes back as RFC 7807
            // rather than an empty 429 the client has to guess at. Retry-After is
            // set when the window's reset time is known, so a well-behaved client
            // backs off for exactly as long as it needs to.
            options.OnRejected = async (context, ct) =>
            {
                if (context.Lease.TryGetMetadata(MetadataName.RetryAfter, out var retryAfter))
                {
                    context.HttpContext.Response.Headers.RetryAfter =
                        ((int)Math.Ceiling(retryAfter.TotalSeconds)).ToString();
                }

                var problemService = context.HttpContext.RequestServices
                    .GetRequiredService<IProblemDetailsService>();

                context.HttpContext.Response.StatusCode = StatusCodes.Status429TooManyRequests;
                await problemService.WriteAsync(new ProblemDetailsContext
                {
                    HttpContext = context.HttpContext,
                    ProblemDetails =
                    {
                        Status = StatusCodes.Status429TooManyRequests,
                        Title = "Too many requests.",
                        Detail = "You have made too many write requests in a short window. Slow down and try again shortly.",
                    },
                });
            };
        });

        return services;
    }

    private static bool IsWrite(string method) =>
        HttpMethods.IsPost(method)
        || HttpMethods.IsPut(method)
        || HttpMethods.IsPatch(method)
        || HttpMethods.IsDelete(method);
}

// BootQuest kata module: a TESTABLE, self-contained adaptation (not a repo file) of tracer-net @ 2c0f21f:
//   src/Tracer.Api/RateLimiting/WriteRateLimiter.cs with the senior review's fix applied (docs/architecture.md:241:
//   partition on the authenticated user, remote address for failed auth; UseRateLimiter after UseAuthentication).
// ASP.NET's HttpContext and PartitionedRateLimiter are replaced by small stand-ins (a request with headers, a
// claims principal, a remote address; one fixed window per partition key, permits counted per window) so the
// partitioning compiles and runs on its own; the write test and the partition-key block are the same code as
// the adapted limiter next to it.
using System.Net;
using System.Security.Claims;

namespace Tracer.Kata;

public static class ApiKeyAuthenticationHandler
{
    public const string HeaderName = "X-Api-Key";
}

/// <summary>Request headers; a missing header reads as "" (StringValues.Empty.ToString()).</summary>
public sealed class HeaderDictionary
{
    private readonly Dictionary<string, string> _values = new(StringComparer.OrdinalIgnoreCase);

    public string this[string name]
    {
        get => _values.TryGetValue(name, out var v) ? v : string.Empty;
        set => _values[name] = value;
    }
}

public sealed class HttpRequest
{
    public string Method { get; set; } = "GET";
    public HeaderDictionary Headers { get; } = new();
}

public sealed class ConnectionInfo
{
    public IPAddress? RemoteIpAddress { get; set; }
}

public sealed class HttpContext
{
    public HttpRequest Request { get; } = new();
    public ConnectionInfo Connection { get; } = new();
    public ClaimsPrincipal User { get; set; } = new(new ClaimsIdentity());
}

public static class PrincipalExtensions
{
    public static string? FindFirstValue(this ClaimsPrincipal principal, string claimType) => principal.FindFirst(claimType)?.Value;
}

/// <summary>The global write limiter: one fixed window (PermitLimit permits) per partition key.</summary>
public sealed class WriteRateLimiter(int permitLimit)
{
    private readonly Dictionary<string, int> _windows = [];

    /// <summary>Partitions (fixed-window limiters) currently held in memory.</summary>
    public int Partitions => _windows.Count;

    /// <summary>true = admitted, false = 429.</summary>
    public bool TryAcquire(HttpContext context)
    {
        var partitionKey = PartitionFor(context);
        if (partitionKey is null)
        {
            return true;
        }

        _windows.TryGetValue(partitionKey, out var used);
        _windows[partitionKey] = used + 1;
        return used < permitLimit;
    }

    /// <summary>The partition a request draws from (null = reads, never throttled).</summary>
    public static string? PartitionFor(HttpContext context)
    {
        if (!IsWrite(context.Request.Method))
        {
            // Reads are never throttled: a NoLimiter partition draws from
            // nothing and rejects nothing.
            return null;
        }

                // Partition on the AUTHENTICATED caller (UseRateLimiter runs after
                // UseAuthentication in this adaptation), never on a header the caller
                // controls: a request whose key failed to authenticate is bucketed by
                // remote address, so guessing keys cannot mint fresh windows.
                var userId = context.User.FindFirstValue(ClaimTypes.NameIdentifier);
                var partitionKey = userId is not null
                    ? $"user:{userId}"
                    : $"ip:{context.Connection.RemoteIpAddress?.ToString() ?? "anonymous"}";

        return partitionKey;
    }

    private static bool IsWrite(string method) =>
        method is "POST" or "PUT" or "PATCH" or "DELETE";
}

