using System.Net;
using System.Security.Claims;
using Tracer.Kata;

public sealed class WriteRateLimiterTests
{
    private static HttpContext Request(string method, string? apiKey = null, string? userId = null, string ip = "203.0.113.7")
    {
        var ctx = new HttpContext();
        ctx.Request.Method = method;
        if (apiKey is not null)
        {
            ctx.Request.Headers[ApiKeyAuthenticationHandler.HeaderName] = apiKey;
        }

        ctx.Connection.RemoteIpAddress = IPAddress.Parse(ip);
        if (userId is not null)
        {
            ctx.User = new ClaimsPrincipal(new ClaimsIdentity([new Claim(ClaimTypes.NameIdentifier, userId)], "ApiKey"));
        }

        return ctx;
    }

    [Fact(DisplayName = "Writes_are_rate_limited_while_reads_are_not (ported from tests/Tracer.Tests/Integration/ProductionReadinessApiTests.cs:120)")]
    public void Writes_are_rate_limited_while_reads_are_not()
    {
        var limiter = new WriteRateLimiter(permitLimit: 3);

        for (var i = 0; i < 8; i++)
        {
            Assert.True(limiter.TryAcquire(Request("GET", "trk_admin", "admin-1")));
        }

        var admitted = Enumerable.Range(0, 5).Select(_ => limiter.TryAcquire(Request("POST", "trk_admin", "admin-1"))).ToList();
        Assert.Equal(3, admitted.Count(a => a));
        Assert.Contains(false, admitted);
    }

    [Fact(DisplayName = "guessing keys cannot mint fresh windows: bogus X-Api-Key values from one address share one bucket (senior review #1, docs/architecture.md:241)")]
    public void KeyGuessing_IsThrottled()
    {
        var limiter = new WriteRateLimiter(permitLimit: 3);

        var admitted = Enumerable.Range(1, 10)
            .Select(i => limiter.TryAcquire(Request("POST", $"trk_guess_{i:0000}")))
            .Count(a => a);

        Assert.Equal(3, admitted);
    }

    [Fact(DisplayName = "the partitions held in memory stay bounded under a flood of unique garbage keys (senior review #1)")]
    public void KeyFlood_KeepsPartitionsBounded()
    {
        var limiter = new WriteRateLimiter(permitLimit: 120);

        for (var i = 0; i < 1000; i++)
        {
            limiter.TryAcquire(Request("POST", $"trk_flood_{i}"));
        }

        Assert.Equal(1, limiter.Partitions);
    }

    [Fact(DisplayName = "an authenticated caller draws from its own bucket, separate from anonymous traffic on the same address")]
    public void AuthenticatedCaller_HasOwnBucket()
    {
        var limiter = new WriteRateLimiter(permitLimit: 1);

        Assert.True(limiter.TryAcquire(Request("POST", "trk_garbage")));
        Assert.True(limiter.TryAcquire(Request("POST", "trk_real", "user-9")));
    }
}
